// REPLACE THIS NODE with your real source (a Modbus, OPC UA or MQTT node, or a Ignition/PLC read).
// It must leave msg.payload = { <wertek variable key>: <number> }. Here it SIMULATES a boiler-feed pump.
const t = Date.now() / 1000, r1 = (x) => Math.round(x * 10) / 10;
msg.payload = {
  flow_m3h:       r1(412.5 + 5   * Math.sin(t / 30)),
  head_m:         r1(85.2  + 0.5 * Math.sin(t / 45)),
  kw:             r1(118.4 + 2   * Math.sin(t / 30)),
  seal_temp_c:    r1(62.3  + 0.4 * Math.sin(t / 60)),
  vibration_mm_s: r1(2.8   + 0.2 * Math.sin(t / 20))
};
msg.simulated = true;
return msg;

// Build one IAES 2.0 asset.measurement per number, and prepare the call. Nothing secret is written here:
// the key and the asset come from the ENVIRONMENT of Node-RED (docs/API_KEY_HANDLING.md, rule 6).
const key = env.get("WERTEK_API_KEY"), asset = env.get("WERTEK_ASSET_ID");
if (!key || !asset) {
  node.error("set WERTEK_API_KEY and WERTEK_ASSET_ID in the environment of Node-RED (the key is never shown)");
  return null;
}
const base = (env.get("WERTEK_BASE_URL") || "https://api.wertek.ai").replace(/\/+$/, "");
const position = env.get("WERTEK_POSITION_CODE") || "pump_process";
// the pump panel's channels: key == channel, unit == the channel's unit (it labels, it does not convert)
const UNITS = { flow_m3h: "m³/h", head_m: "m", kw: "kW", pf: "1", vibration_mm_s: "mm/s",
                bearing_temp_c: "°C", winding_temp_c: "°C", seal_temp_c: "°C" };
const uuid = () => "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
  const r = Math.random() * 16 | 0; return (c === "x" ? r : (r & 3 | 8)).toString(16); });
const when = new Date().toISOString().replace(/\.\d{3}Z$/, "Z"), corr = uuid(), events = [], skipped = [];
for (const [k, v] of Object.entries(msg.payload || {})) {
  if (!(k in UNITS) || typeof v !== "number" || !isFinite(v)) { skipped.push(k); continue; }  // never invent a value
  events.push({ spec_version: "2.0", event_id: uuid(), correlation_id: corr, event_type: "asset.measurement",
    timestamp: when, source: "wertek_integrations.node_red",
    dataschema: "https://iaes.dev/schema/v2/asset.measurement", asset: { asset_id: asset },
    data: { measurement_type: k, value: v, unit: UNITS[k], location: position } });
}
if (!events.length) { node.warn("nothing to send; skipped: " + skipped.join(", ")); return null; }
msg.events = events; msg.skipped = skipped;
msg.method = "POST"; msg.url = base + "/iaes/ingest";
msg.headers = { "X-API-Key": key, "Content-Type": "application/json", "User-Agent": "wertek-integrations-node-red/1.0" };
msg.payload = events;
return msg;

// One answer per event. A batch where NOTHING was accepted answers HTTP 422 and still carries them:
// it is an answer, not a failure. 504 = faster than the contracted cadence (dropped, retryable).
const by = {}; ((msg.payload && msg.payload.results) || []).forEach((x) => { by[x.event_id] = x; });
const answers = msg.events.map((e) => { const x = by[e.event_id] || {};
  return { key: e.data.measurement_type, value: e.data.value, c: x.c, d: x.d || null }; });
const fine = new Set([100, 101, 102, 504]);
const bad = answers.filter((a) => !fine.has(a.c));
if (bad.length) node.warn("not stored: " + bad.map((a) => a.key + "=" + a.c).join(", "));
msg.payload = { http: msg.statusCode, answers, skipped: msg.skipped, ok: bad.length === 0 };
return msg;
